-- public.bait_in_pack(p_world uuid, p_uid uuid, p_species text, p_any boolean)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.bait_in_pack(p_world uuid, p_uid uuid, p_species text, p_any boolean DEFAULT false)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select i.def from item i
  where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
    and (is_bait_for(p_species, i.def)
         or (p_any and coalesce((select d.food from item_def d where d.id = i.def), 0) > 0))
  order by i.id limit 1
$function$
